		let years = today.getUTCFullYear() - diedAt.getUTCFullYear();
		if (died.length > 4 && today.getTime() < Date.UTC(today.getUTCFullYear(), diedAt.getUTCMonth(), diedAt.getUTCDate())) {
			years -= 1;
		}
		sentences.push(
			years < 1
				? "I've been here less than a year."
				: `I've been here ${years} ${years === 1 ? 'year' : 'years'}.`
		);
	}
