		if (!yearsAgree(year(died), year(inscription.died))) continue;
		const known = (a: string | null, b: string | null) => Number(!!a && !!b);
		scored.push({
			candidate: { name: c.name.trim(), born, died, place: c.place?.trim() || null, sources },
			score:
				Number(c.name.trim().toLowerCase() === inscription.name.toLowerCase()) +
				known(year(born), year(inscription.born)) +
				known(year(died), year(inscription.died))
		});
	}
	return scored
		.sort((a, b) => b.score - a.score)
		.slice(0, MAX_CANDIDATES)
		.map((s) => s.candidate);
