			{#if retry}<button type="button" onclick={() => retry?.()}>Try again</button>{/if}
		</div>
	{/if}

	{#if person && phase !== 'capture' && phase !== 'pick'}
		<dl class="stone" aria-label="Read from the stone">
			<dt>Name</dt>
			<dd>{person.name}</dd>
			<dt>Born</dt>
			<dd>{show(person.born)}</dd>
			<dt>Died</dt>
			<dd>{show(person.died)}</dd>
		</dl>
	{/if}

	{#if phase === 'capture'}
		<label class="primary">
			Photograph a headstone
			<input type="file" accept="image/*" capture="environment" onchange={onPhoto} hidden />
		</label>
	{:else if phase === 'reading'}
		<p role="status">Reading the stone…</p>
	{:else if phase === 'pick'}
		<h2>Whose story?</h2>
		<ul class="list">
			{#each people as p (p.carvedName + p.born + p.died)}
				<li>
					<button type="button" onclick={() => research(p)}>
						<strong>{p.name}</strong>
						<span>{show(p.born)} – {show(p.died)}</span>
					</button>
				</li>
			{/each}
		</ul>
	{:else if phase === 'researching'}
		<p role="status">Searching public records…</p>
	{:else if phase === 'confirm'}
		<h2>Is this them?</h2>
		<ul class="list">
			{#each candidates as c (c.sources[0].id)}
				<li>
					<strong>{c.name}</strong>
					<span>{show(c.born)} – {show(c.died)}{c.place ? ` · ${c.place}` : ''}</span>
					<ul class="links">
						{#each c.sources as s (s.id)}
							<li>
								<a href={s.url} target="_blank" rel="noopener noreferrer">{s.title || s.site}</a>
								<small>{s.site}</small>
							</li>
						{/each}
					</ul>
					<button type="button" onclick={() => tell(c)}>This is them</button>
				</li>
			{/each}
		</ul>
		<button type="button" class="quiet" onclick={() => showEpitaph(NOTES.none)}>
			None of these
		</button>
	{:else if phase === 'telling'}
		<p role="status">Listening for {confirmed?.name}…</p>
	{:else if phase === 'story' && story}
		<p class="label">AI-generated historical reconstruction</p>
		<div class="story">
			{#each story.sentences as s, i (i)}
				{#if s.kind === 'fact'}
					<p class="fact">
						{s.text}
						{#each s.sourceIds as id (id)}
							{@const src = source(id)}
							{#if src}<a href={src.url} target="_blank" rel="noopener noreferrer">[{src.site}]</a>{/if}
						{/each}
					</p>
				{:else}
					<p class="reconstruction"><span class="tagged">Imagined</span> {s.text}</p>
				{/if}
			{/each}
		</div>
		<h2>Sources</h2>
		<ul class="links">
			{#each story.sources as s (s.id)}
				<li><a href={s.url} target="_blank" rel="noopener noreferrer">{s.title || s.site}</a></li>
			{/each}
		</ul>
		<button type="button" onclick={() => reset()}>Try another photo</button>
	{:else if phase === 'epitaph' && person}
		<div class="story">
			{#each epitaph(person, new Date()) as line (line)}
				<p class="fact">{line}</p>
			{/each}
		</div>
		<p class="note">{epitaphNote}. Source: the headstone.</p>
		<button type="button" onclick={() => reset()}>Try another photo</button>
	{/if}
</main>

