		const [c] = resolve([rec('Gaynor Hawks was a beloved piano teacher in Alsea.')]);
		expect(c.confidence).toBe('low');
		expect(c.sources).toHaveLength(1);
		expect([c.born, c.died]).toEqual([null, null]);
	});

