import { Agent } from '@mastra/core/agent';
import { z } from 'zod';
import type { Candidate, Inscription } from '#lib/types.ts';
import { geminiApiKey } from '../env';
import { ProviderError } from '../http';
import type { InferenceProvider, PageText, RawPerson, RawFact } from './index';

const MODEL_ID = 'google/gemma-4-26b-a4b-it';
const MAX_RETRIES = 2;

// Gemma 4 thinks ~5k tokens by default, which takes minutes on long prompts.
const NO_THINKING = { google: { thinkingConfig: { thinkingLevel: 'minimal' } } } as const;

const dateHint = 'YYYY-MM-DD or YYYY; ? for an unreadable digit; null if absent.';

/** The only definition of the read output shape. */
export const readSchema = z.object({
	people: z.array(
		z.object({
			name: z.string().describe('Name exactly as carved.'),
			born: z.string().nullable().describe(dateHint),
			died: z.string().nullable().describe(dateHint)
		})
	)
});

/** Rules measured in benchmark run 10. */
export const READ_INSTRUCTIONS = `You read photos of gravestones for a historical research tool.

Transcribe ONLY what is carved or cast on the stone. Do NOT add, guess, or complete anything you cannot see.

- people: one entry per person commemorated, with the name exactly as carved. [] if no name is legible.
- Only the person or people the stone is for go in people. Relatives named in relation to them ("son of", "wife of", "daughter of") and nicknames are NOT separate people.
- born/died: "YYYY-MM-DD", or "YYYY" when only the year is carved. Use "?" for an unreadable digit, and for any worn digit that could be read two ways (1 or 4, 3 or 8). A "?" is better than a guess. null when the date is not on the stone.
- A surname carved once, at the top or the bottom of a stone shared by two people, belongs to every person on the stone. Put it on each name, e.g. "ANN MARIE" and "JOHN PAUL" under "BRANDT" are "Ann Marie Brandt" and "John Paul Brandt". Give each person only the dates carved for them, and null for a date that is not carved for them.
- A year that is not a birth or death (marriage length, erection date) is NOT a life date.`;

export const READ_USER_TEXT = 'Transcribe the gravestone in this photo.';
export const READ_SAMPLING = { temperature: 0, topP: 0.95, topK: 64 };

const factsSchema = z.object({
	facts: z.array(
		z.object({
			claim: z.enum(['name', 'birth', 'death', 'other']),
			sourceId: z.string(),
			quote: z.string().describe('Copied exactly from the source text, under 25 words.')
		})
	)
});

const EXTRACT_INSTRUCTIONS = `Task: pull checkable facts about one deceased person out of source texts.

Rules:
- Return only facts the sources state about this person, each as claim, sourceId and quote.
- quote is copied exactly from the source text, with no edits. Keep it short: one phrase or sentence, under 25 words.
- claim is "name", "birth" or "death" for those facts, and "other" for anything else: work, hobbies, places lived, family relationships, achievements.
- Skip facts about other people, unless the fact states this person's relationship to them. Never include the names of survivors or other living people.
- Skip guesses, opinions and anything the text does not say.
- If the sources hold no usable facts, return an empty list.`;

const STORY_INSTRUCTIONS = `Task: write a short theatrical monologue spoken by a ghost, built around a list of verified facts.

Rules:
- Write one paragraph of 100 to 170 words, in first person as the deceased, spoken to a visitor at the grave.
- Weave in as many of the facts as read naturally. State each fact plainly and truthfully.
- Add atmosphere around the facts: the grave, the dark, the stone, the weather, time, the visitor. Make it eerie, dramatic and intimate. It is openly fiction.
- Use only the facts given. Do not add any name, place, number, date, event, relationship, memory, thought or feeling of the deceased that the facts do not state. Do not deny or reverse a fact.
- Never name anyone the facts do not name, and never name living people.
- A voice actor will read it aloud: use plain flowing sentences. No stage directions, brackets, parentheses, emoji, markdown, headings or lists. Use commas, periods and ellipses for pauses.
- Output only the paragraph.`;

/**
 * Builds a one-shot Mastra agent on the hosted Gemma model.
 * @param id Agent id.
 * @param instructions System instructions.
 * @returns The agent.
 */
function agent(id: string, instructions: string): Agent {
	return new Agent({
		id,
		name: id,
		instructions,
		model: { id: MODEL_ID, apiKey: geminiApiKey() },
		maxRetries: MAX_RETRIES
	});
}

/**
 * Wraps a failed model call in a {@link ProviderError}.
 * @param what Operation name for the message.
 * @param e Caught error.
 * @returns The wrapped error, ready to throw.
 */
function failed(what: string, e: unknown): ProviderError {
	return new ProviderError(`${what} failed`, { cause: e });
}

/** Gemma 4 26B on the Gemini API via Mastra. */
export class GemmaProvider implements InferenceProvider {
	/** @inheritdoc */
	async readStone(image: Uint8Array, mimeType: string): Promise<RawPerson[]> {
		try {
			const res = await agent('read-stone', READ_INSTRUCTIONS).generate(
				[
					{
						role: 'user',
						content: [
							{ type: 'image', image: Buffer.from(image).toString('base64'), mimeType },
							{ type: 'text', text: READ_USER_TEXT }
						]
					}
				],
				{ structuredOutput: { schema: readSchema }, modelSettings: READ_SAMPLING }
			);
			return res.object.people;
		} catch (e) {
			throw failed('Reading the stone', e);
		}
	}

	/** @inheritdoc */
	async extractFacts(
		inscription: Inscription,
		candidate: Candidate,
		pages: PageText[]
	): Promise<RawFact[]> {
		const sources = candidate.sources.map(({ id, title }) => ({
			id,
			title,
			text: pages.find((p) => p.sourceId === id)?.text ?? ''
		}));
		try {
			const res = await agent('extract-facts', EXTRACT_INSTRUCTIONS).generate(
				`Person: ${candidate.name} (headstone: ${inscription.carvedName}).\n\nSources:\n${JSON.stringify(sources)}`,
				{
					structuredOutput: { schema: factsSchema },
					modelSettings: { temperature: 0 },
					providerOptions: NO_THINKING
				}
			);
			return res.object.facts;
		} catch (e) {
			throw failed('Extracting facts', e);
		}
	}

	/** @inheritdoc */
	async tellStory(name: string, facts: string[]): Promise<string> {
		try {
			const res = await agent('tell-story', STORY_INSTRUCTIONS).generate(
				`Deceased: ${name}\n\nVerified facts:\n${facts.map((f) => `- ${f}`).join('\n')}`,
				{
					// Gemma's documented sampling for every use case; the creative call needs the variety.
					modelSettings: { temperature: 1, topP: 0.95, topK: 64 },
					providerOptions: NO_THINKING
				}
			);
			return res.text.trim();
		} catch (e) {
			throw failed('Telling the story', e);
		}
	}
}

export const inference: InferenceProvider = new GemmaProvider();

import { lookup } from 'node:dns/promises';
import { BlockList, isIP } from 'node:net';
import { Agent } from 'undici';
import { Readability } from '@mozilla/readability';
import { parseHTML } from 'linkedom';
import robotsParser from 'robots-parser';

const USER_AGENT = 'Gravespeaker';
const MAX_REDIRECTS = 3;
const MAX_BYTES = 2 * 1024 * 1024;
const TIMEOUT_MS = 8000;

// Deny-list ranges, not endpoints: the NOSONAR markers silence S1313.
const blocked = new BlockList();
for (const [net, bits] of [
	['0.0.0.0', 8],
	['10.0.0.0', 8], // NOSONAR
	['100.64.0.0', 10], // NOSONAR
	['127.0.0.0', 8],
	['169.254.0.0', 16], // NOSONAR
	['172.16.0.0', 12], // NOSONAR
	['192.168.0.0', 16], // NOSONAR
	['192.0.0.0', 24],
	['192.0.2.0', 24],
	['198.18.0.0', 15],
	['198.51.100.0', 24],
	['203.0.113.0', 24],
	['224.0.0.0', 4],
	['240.0.0.0', 4]
] as const) {
	blocked.addSubnet(net, bits, 'ipv4');
}
blocked.addAddress('::', 'ipv6');
blocked.addAddress('::1', 'ipv6');
blocked.addSubnet('fe80::', 10, 'ipv6'); // NOSONAR
blocked.addSubnet('fc00::', 7, 'ipv6'); // NOSONAR
blocked.addSubnet('ff00::', 8, 'ipv6');
// NAT64, 6to4 and Teredo can encode a private IPv4 destination.
blocked.addSubnet('64:ff9b::', 96, 'ipv6');
blocked.addSubnet('2002::', 16, 'ipv6');
blocked.addSubnet('2001::', 32, 'ipv6');

/**
 * Resolves a host once and returns the address to connect to, or null when any address is non-public.
 * @param hostname URL hostname.
 * @returns A public address to pin the connection to.
 */
async function resolvePublic(
	hostname: string
): Promise<{ address: string; family: number } | null> {
	const host = hostname.replace(/^\[|\]$/g, '');
	const family = isIP(host);
	const addresses = family
		? [{ address: host, family }]
		: await lookup(host, { all: true }).catch(() => []);
	const ok =
		addresses.length > 0 &&
		addresses.every((a) => !blocked.check(a.address, a.family === 6 ? 'ipv6' : 'ipv4'));
	return ok ? addresses[0] : null;
}

/**
 * Fetches one URL, following up to 3 redirects and re-checking every hop against the SSRF guard.
 * @param start First URL.
 * @param allowed Optional per-hop gate; a false answer for any hop, the first included, yields null.
 * @returns The final response, or null when blocked, failed or redirected too often.
 */
async function guardedFetch(
	start: string,
	allowed?: (url: URL) => Promise<boolean>
): Promise<Response | null> {
	let url = start;
	for (let hop = 0; hop <= MAX_REDIRECTS; hop++) {
		let parsed: URL;
		try {
			parsed = new URL(url);
		} catch {
			return null;
		}
		if (!/^https?:$/.test(parsed.protocol)) return null;
		if (allowed && !(await allowed(parsed))) return null;
		const target = await resolvePublic(parsed.hostname);
		if (!target) return null;
		// Connecting to the checked address closes the gap where DNS answers differently on a second lookup.
		const dispatcher = new Agent({
			keepAliveTimeout: 1,
			connect: {
				lookup: (_host, options, callback) =>
					options.all ? callback(null, [target]) : callback(null, target.address, target.family)
			}
		});
		let res: Response;
		try {
			res = await fetch(parsed, {
				dispatcher,
				redirect: 'manual',
				headers: { 'User-Agent': USER_AGENT },
				signal: AbortSignal.timeout(TIMEOUT_MS)
			} as RequestInit); // lib.dom's RequestInit lacks undici's `dispatcher`
		} catch {
			return null;
		}
		// nosemgrep: javascript.browser.tainted-redirect.tainted-redirect -- followed server-side; every hop re-runs the SSRF check.
		const location = res.headers.get('location');
		if (res.status >= 300 && res.status < 400 && location) {
			try {
				url = new URL(location, parsed).href;
			} catch {
				return null;
			}
			continue;
		}
		return res;
	}
	return null;
}

/**
 * Reads a response body up to the byte cap.
 * @param res Response to read.
 * @returns Decoded text truncated at the cap, or null when the stream fails mid-read.
 */
async function readCapped(res: Response): Promise<string | null> {
	const reader = res.body?.getReader();
	if (!reader) return '';
	const chunks: Uint8Array[] = [];
	let size = 0;
	try {
		while (size < MAX_BYTES) {
			const { done, value } = await reader.read();
			if (done) break;
			chunks.push(value);
			size += value.length;
		}
	} catch {
		return null;
	} finally {
		await reader.cancel().catch(() => undefined);
	}
	return Buffer.concat(chunks).subarray(0, MAX_BYTES).toString('utf8');
}

/**
 * Builds a per-call robots gate that fetches each origin's robots.txt at most once.
 * @returns A hop check: true when that origin's robots.txt permits Gravespeaker to fetch the URL.
 */
function robotsGate(): (url: URL) => Promise<boolean> {
	const cache = new Map<string, Promise<(href: string) => boolean>>();
	/**
	 * Loads one origin's robots.txt and returns its verdict function.
	 * @param origin Origin to load robots.txt from.
	 * @returns A permission check. A 4xx robots.txt means no rules (allow all). Per RFC 9309 an
	 * unreachable, 5xx or unreadable one means disallow all.
	 */
	const load = async (origin: string): Promise<(href: string) => boolean> => {
		const res = await guardedFetch(`${origin}/robots.txt`);
		if (!res || res.status >= 500) return () => false;
		if (!res.ok) return () => true;
		const body = await readCapped(res);
		if (body === null) return () => false;
		const robots = robotsParser(`${origin}/robots.txt`, body);
		return (href) => robots.isAllowed(href, USER_AGENT) !== false;
	};
	return async (url) => {
		let verdict = cache.get(url.origin);
		if (!verdict) {
			verdict = load(url.origin);
			cache.set(url.origin, verdict);
		}
		return (await verdict)(url.href);
	};
}

/**
 * Fetches a page and extracts its main text. Nothing is persisted.
 * @param url Source URL from a search record.
 * @returns Readable text, or null when blocked, disallowed, gated, non-HTML, unreadable or empty.
 */
export async function fetchPage(url: string): Promise<string | null> {
	const res = await guardedFetch(url, robotsGate());
	if (!res?.ok || !res.headers.get('content-type')?.includes('html')) return null;
	const body = await readCapped(res);
	if (body === null) return null;
	const { document } = parseHTML(body);
	const text = new Readability(document as unknown as Document).parse()?.textContent;
	return text?.replace(/\s+/g, ' ').trim() || null;
}

import { afterEach, describe, expect, it, vi } from 'vitest';

vi.mock('#lib/server/env.ts', () => ({ geminiApiKey: () => 'test', serpApiKey: () => 'test' }));

const { POST } = await import('./+server');

const stone = {
	carvedName: 'Gaynor Claire Hawks',
	name: 'Gaynor Claire Hawks',
	maidenName: null,
	born: '1932-03-10',
	died: '2017-12-27'
};

/**
 * Stubs the SerpApi boundary. Every engine answers with the same handler.
 * @param serp Handler for SerpApi.
 */
const stub = (serp: () => Response): void => {
	vi.stubGlobal(
		'fetch',
		vi.fn(async () => serp())
	);
};

const hits = {
	organic_results: [
		{
			link: 'https://legacy.com/hawks',
			title: 'Gaynor Hawks obituary',
			snippet: 'Gaynor Claire Hawks (1932-2017)'
		},
		{ link: 'https://ancestry.com/x', title: 'Gated', snippet: 'Gaynor Hawks 1932' }
	]
};

/**
 * Calls the endpoint.
 * @param body JSON body.
 * @returns The response.
 */
const call = (body: unknown) =>
	POST({
		request: new Request('http://x/api/research', { method: 'POST', body: JSON.stringify(body) })
	} as never);

afterEach(() => vi.unstubAllGlobals());

describe('POST /api/research', () => {
	it('rejects an invalid body', async () => {
		const res = await call({ name: 'x' });
		expect(res.status).toBe(400);
		expect((await res.json()).error.code).toBe('invalid_input');
	});

	it('returns no candidates when search finds nothing', async () => {
		stub(() => Response.json({}));
		const res = await call(stone);
		expect(res.status).toBe(200);
		expect(await res.json()).toEqual({ candidates: [] });
	});

	it('returns the matching candidate with gated sites removed and duplicates merged', async () => {
		stub(() => Response.json(hits));
		const res = await call(stone);
		expect(res.status).toBe(200);
		const { candidates } = await res.json();
		expect(candidates).toHaveLength(1);
		expect(candidates[0].confidence).toBe('high');
		expect(candidates[0].sources.map((s: { url: string }) => s.url)).toEqual([
			'https://legacy.com/hawks'
		]);
	});

	it('returns the right person even when the death date is not mentioned', async () => {
		stub(() =>
			Response.json({
				organic_results: [
					{
						link: 'https://a.com/1',
						title: 'Obit',
						snippet: 'Gaynor Hawks, born 1932, taught piano.'
					}
				]
			})
		);
		const { candidates } = await (await call(stone)).json();
		expect(candidates).toHaveLength(1);
		expect(candidates[0].confidence).toBe('medium');
	});

	it('leaves out a result that names someone else', async () => {
		stub(() =>
			Response.json({
				organic_results: [
					{ link: 'https://x.com/a', title: 'Unrelated', snippet: 'Smith 1932 2017' }
				]
			})
		);
		expect(await (await call(stone)).json()).toEqual({ candidates: [] });
	});

	it('returns 502 when search fails on every attempt', async () => {
		stub(() => Response.json({ error: 'down' }, { status: 500 }));
		const res = await call(stone);
		expect(res.status).toBe(502);
		expect((await res.json()).error.code).toBe('provider_failed');
	}, 60_000);
});

